githubEnv.run:
set -euo pipefail

case "${RELEASE_TRACK}" in
  internal) play_track="internal" ;;
  open) play_track="beta" ;;
  production) play_track="production" ;;
  *)
    echo "::error::Unknown release track: ${RELEASE_TRACK}"
    exit 1
    ;;
esac

echo "PLAY_TRACK=${play_track}" >> "${GITHUB_ENV}"
echo "Release track ${RELEASE_TRACK} uploads to the Google Play ${play_track} track."

step.run:
set -euo pipefail
checks=$(gh api --paginate --slurp "repos/${GITHUB_REPOSITORY}/commits/${SOURCE_SHA}/check-runs?per_page=100")
for workflow in test guards; do
  runs=$(gh api --paginate --slurp "repos/${GITHUB_REPOSITORY}/actions/workflows/${workflow}.yml/runs?head_sha=${SOURCE_SHA}&per_page=100")
  suite=$(jq -er --arg sha "$SOURCE_SHA" --arg path ".github/workflows/${workflow}.yml" '
    [.[] | .workflow_runs[] | select(.head_sha == $sha and .path == $path and (.event == "push" or .event == "workflow_dispatch"))]
    | max_by([.run_number, .run_attempt])
    | select(.status == "completed" and .conclusion == "success") | .check_suite_id' <<< "$runs") || {
    echo "::error::Selected SHA requires a successful ${workflow}.yml push or workflow_dispatch run; dispatch test.yml and guards.yml on that ref, then rerun the release"; exit 1;
  }
  jq -e --arg sha "$SOURCE_SHA" --argjson suite "$suite" '
    [.[] | .check_runs[] | select(.check_suite.id == $suite)]
    | length > 0 and all(.[]; .head_sha == $sha and .app.id == 15368 and .status == "completed"
      and (.conclusion == "success" or .conclusion == "neutral" or .conclusion == "skipped"))' <<< "$checks" >/dev/null || {
    echo "::error::Selected SHA has missing or failing checks for ${workflow}.yml"; exit 1;
  }
done

set -euo pipefail

case "${RELEASE_TRACK}" in
  internal) play_track="internal" ;;
  open) play_track="beta" ;;
  production) play_track="production" ;;
  *)
    echo "::error::Unknown release track: ${RELEASE_TRACK}"
    exit 1
    ;;
esac

echo "PLAY_TRACK=${play_track}" >> "${GITHUB_ENV}"
echo "Release track ${RELEASE_TRACK} uploads to the Google Play ${play_track} track."

githubEnv.run:
set -euo pipefail
gh run list --repo "$GH_REPO" --workflow android-release.yml --branch main --status success --limit 100 --json displayTitle |
  node --input-type=module -e '
    import { appendFileSync, readFileSync } from "node:fs";
    const runs = JSON.parse(readFileSync(0, "utf8"));
    const release = runs.map((run) => /^Android Release (\d+\.\d+\.\d+) \(\d+\) to (?:open|production) on main$/.exec(run.displayTitle)).find(Boolean);
    if (!release) throw new Error("No successful production Android release version found");
    appendFileSync(process.env.GITHUB_ENV, `ORBIT_APP_VERSION=${release[1]}\n`);
    console.log(`Startup proof uses ${release[0]}`);
  '

